from pathlib import Path
import json,html
from network_data import TECHS,MEDINA,SSP,FLOWS
D=json.loads(Path('/workspace/outils-puissants/data.json').read_text())
def row(letter,i,t):
 n,f,s,u,core,simple=t
 cls=' class="priority-tool"' if core else ''
 return f'<tr{cls}><th scope="row"><a href="{u}" target="_blank" rel="noopener noreferrer">{html.escape(n)}<span class="ext" aria-hidden="true">↗</span></a><small>{letter}{i:02}</small>{"<span class=\"priority-label\">Usage intensif</span>" if core else ""}</th><td>{html.escape(f)}</td><td><span class="technical-copy">{html.escape(s)}</span><button class="plain-toggle" type="button" aria-expanded="false">Vulgariser</button><span class="plain-copy" hidden>{html.escape(simple)}</span></td></tr>' 
for l,items in D.items():
 D[l]='\n'.join(row(l,i,t) for i,t in enumerate(items,1))
